package com.campus.lostfound.repository; import com.campus.lostfound.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface ItemRepository extends JpaRepository<Item,Long>{ @Query("select i from Item i where i.status=:status and (:q is null or lower(i.name) like lower(concat('%',:q,'%'))) and (:cat is null or i.category=:cat) and (:loc is null or lower(i.location) like lower(concat('%',:loc,'%'))) order by i.createdAt desc") List<Item> search(@Param("status") ItemStatus s,@Param("q") String q,@Param("cat") String cat,@Param("loc") String loc); List<Item> findByReporterIdOrderByCreatedAtDesc(Long id); List<Item> findByStatusOrderByCreatedAtDesc(ItemStatus s); long countByStatus(ItemStatus s); }